config:
daemon off;
master_process on;
worker_processes 1;
pid /tmp/research-nginx-config-vn8ng4bw/nginx.pid;
error_log stderr notice;
events { worker_connections 128; use epoll; multi_accept off; accept_mutex off; }
http {
client_body_temp_path /tmp/research-nginx-config-vn8ng4bw/client;
proxy_temp_path /tmp/research-nginx-config-vn8ng4bw/proxy;
fastcgi_temp_path /tmp/research-nginx-config-vn8ng4bw/fastcgi;
uwsgi_temp_path /tmp/research-nginx-config-vn8ng4bw/uwsgi;
scgi_temp_path /tmp/research-nginx-config-vn8ng4bw/scgi;
    access_log off;
    sendfile off;
    aio off;
    keepalive_timeout 0;
    client_header_timeout 10s;
    client_body_timeout 10s;
    send_timeout 10s;
    server {
        listen 8080;
        location = /health { stub_status; gzip off; }
        location = /compress {
            alias /input/corpus.ndjson;
            default_type application/x-ndjson;
            gzip on;
            gzip_comp_level 6;
            gzip_min_length 20;
            gzip_types application/x-ndjson;
            add_header X-Request-ID $http_x_request_id always;
        }
        location / { return 404; }
    }
}
